use std::collections::HashSet;

fn has_common_element(a: &Vec<i32>, b: &Vec<i32>) -> bool {
    // To efficiently check for common elements, we use a HashSet.
    // Insert all elements from the smaller array into the HashSet,
    // then iterate over the other array checking membership.
    //
    // This approach gives average O(n + m) time complexity,
    // where n and m are the lengths of the two arrays.
    //
    // Since arrays are guaranteed non-empty, no need for empty checks.

    if a.len() <= b.len() {
        let set: HashSet<i32> = a.iter().cloned().collect();
        b.iter().any(|val| set.contains(val))
    } else {
        let set: HashSet<i32> = b.iter().cloned().collect();
        a.iter().any(|val| set.contains(val))
    }
}